#!/usr/bin/env bash
# Installa o aggiorna la chat (progetti, ricerca web, lettura pagine, foto, PDF, app installabile) su https://ai.roomandrelax.it/chat/
# Da eseguire sulla macchina Ubuntu. Non tocca gli altri siti del Caddy (es. navetta). Ripetibile.
set -euo pipefail
SUDO="${SUDO-sudo}"
DEST="${DEST:-/var/www/giot-chat}"
CF="${CF:-/etc/caddy/Caddyfile}"
HOST="${HOST_NAME:-ai.roomandrelax.it}"
KBASE="${KATEX_BASE:-https://cdn.jsdelivr.net/npm/katex@0.16.9/dist}"
PBASE="${PDFJS_BASE:-https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build}"
LBASE="${PDFLIB_BASE:-https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist}"

echo "1/7 Copio l'app in $DEST"
$SUDO mkdir -p "$DEST"
